exercise.referenceSolution:
struct Base { virtual int transform(int x) const = 0; virtual ~Base() = default; };
class Offset : public Base { int offset_; public: explicit Offset(int x) : offset_(x) {} int transform(int x) const override { return x+offset_; } };
int solve(int a,int b) { const Offset f{b}; const Base& base=f; return base.transform(a); }
